package de.s04tv.fireedition;

import android.webkit.WebView;
import org.json.JSONObject;

/**
 * Presentation-only HTML/CSS for the original Salesforce login page.
 * Does not change form fields, values, submit events or authentication URLs.
 */
final class LoginTvOverlay {
    private LoginTvOverlay() {}

    private static final String CSS = "\nhtml,body{background:#04182e!important;color:#f7fbff!important;min-height:100%!important}\nbody{font-family:Arial,Roboto,sans-serif!important}\n#s04tv-fire-header{position:relative;z-index:2147483000;pointer-events:none;\nmargin:12px auto 14px;max-width:790px;padding:12px 28px;box-sizing:border-box;\ntext-align:center;color:#fff!important}\n#s04tv-fire-header .s04tv-mark{font-size:clamp(27px,3.4vw,46px);font-weight:900;letter-spacing:.035em}\n#s04tv-fire-header .s04tv-mark strong{color:#00b1eb}\n#s04tv-fire-header .s04tv-subtitle{font-size:clamp(14px,1.3vw,19px);color:#b8d5e9;margin-top:5px}\nbody input[type=email],body input[type=text],body input[type=password],body input[autocomplete=username],\nbody input[autocomplete=current-password],body .slds-input{\n  box-sizing:border-box!important;min-height:58px!important;min-width:0!important;\n  border:2px solid #4a7593!important;border-radius:12px!important;\n  background:#0b2b4a!important;color:#fff!important;\n  font-size:clamp(19px,1.8vw,25px)!important;padding:12px 16px!important;\n  caret-color:#00b1eb!important}\nbody input::placeholder{color:#a8c4d7!important;opacity:1!important}\nbody input:focus,body input:focus-visible,body button:focus-visible,body a:focus-visible,\nbody .slds-input:focus,body [role=button]:focus-visible{\n  outline:4px solid #00b1eb!important;outline-offset:4px!important;\n  box-shadow:0 0 0 6px rgba(0,177,235,.19)!important}\nbody button:not([title]),body button[type=submit],body input[type=submit],\nbody .slds-button_brand,body .slds-button--brand{\n  min-height:54px!important;border-radius:12px!important;padding:11px 24px!important;\n  font-size:clamp(18px,1.6vw,23px)!important;font-weight:700!important}\nbody button[type=submit],body input[type=submit],body .slds-button_brand,body .slds-button--brand{\n  background:#00b1eb!important;border-color:#00b1eb!important;color:#061e36!important}\nbody label,body .slds-form-element__label{font-size:18px!important;color:#edf8ff!important}\nbody a{color:#54d5ff!important}\nbody .slds-card,body .login-card,body .loginCard,body .login-container,body .loginContainer{\n  border-radius:18px!important}\n@media (max-height:600px){\n #s04tv-fire-header{padding:4px 20px;margin:6px auto}\n #s04tv-fire-header .s04tv-mark{font-size:26px}\n #s04tv-fire-header .s04tv-subtitle{font-size:14px}\n body input[type=email],body input[type=text],body input[type=password],body .slds-input{min-height:48px!important}\n}";

    static void apply(WebView webView) {
        if (webView == null) return;
        String js = "(function(){\nif(location.protocol!=='https:'||location.hostname!=='account.schalke04.de')return;\nvar path=location.pathname.toLowerCase();\nif(!/^(\\/|\\/login\\/?|\\/s\\/login\\/?)$/.test(path))return;\nvar css=CSS_WILL_BE_ADDED;\nfunction install(root){\nif(!root||!root.querySelector)return;\ntry{\nif(!root.querySelector('#s04tv-fire-style')){\n var st=document.createElement('style');st.id='s04tv-fire-style';st.textContent=css;root.appendChild(st);\n}\n}catch(ignore){}\n}\ninstall(document.head||document.documentElement);\nif(document.body&&!document.getElementById('s04tv-fire-header')){\n var header=document.createElement('div');header.id='s04tv-fire-header';\n header.innerHTML='<div class=\"s04tv-mark\">S04<strong>TV+</strong></div><div class=\"s04tv-subtitle\">Mit deinem Schalke-Konto anmelden · Steuerkreuz & OK zum Bedienen</div>';\n document.body.insertBefore(header,document.body.firstChild);\n}\nfunction shadowStyles(root,depth){\n if(!root||depth>4)return;\n try{\n var elements=root.querySelectorAll('*');\n for(var i=0;i<elements.length;i++){\n  var el=elements[i];if(el.shadowRoot){install(el.shadowRoot);shadowStyles(el.shadowRoot,depth+1);}\n }\n }catch(ignore){}\n}\nshadowStyles(document,0);\nif(!window.__s04tvTvStyleTimer){\n var passes=0;\n window.__s04tvTvStyleTimer=setInterval(function(){\n  if(location.hostname!=='account.schalke04.de'||++passes>35){\n   clearInterval(window.__s04tvTvStyleTimer);window.__s04tvTvStyleTimer=null;return;\n  }\n  install(document.head||document.documentElement);\n  shadowStyles(document,0);\n },500);\n}\n})();".replace("CSS_WILL_BE_ADDED", JSONObject.quote(CSS));
        webView.evaluateJavascript(js, null);
    }
}
